import fs from 'node:fs';
import path from 'node:path';
import ts from 'typescript';

const root = '/Users/stark/Desktop/work/RN/heals-app-rn';
const changed = fs.readFileSync('/tmp/heals-pr540-changed-ts.txt','utf8').trim().split('\n')
  .map(f => path.join(root, f));

const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('readConfigFile', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root, undefined, configPath);
console.log('parseErrors', parsed.errors.length);
console.log('fileCount', parsed.fileNames.length);
const includeSet = new Set(parsed.fileNames.map(f => path.resolve(f)));
const changedAbs = changed.map(f => path.resolve(f));
const inProgram = changedAbs.filter(f => includeSet.has(f));
const notInProgram = changedAbs.filter(f => !includeSet.has(f));
console.log('changedInProgram', inProgram.length);
console.log('changedNotInProgram', notInProgram.map(f => path.relative(root,f)));

const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
});

const format = (diag, fileHint) => {
  const file = diag.file ? path.relative(root, diag.file.fileName) : fileHint || '';
  let line = 0, col = 0;
  if (diag.file && typeof diag.start === 'number') {
    const pos = diag.file.getLineAndCharacterOfPosition(diag.start);
    line = pos.line + 1;
    col = pos.character + 1;
  }
  const code = `TS${diag.code}`;
  const cat = ts.DiagnosticCategory[diag.category];
  const msg = ts.flattenDiagnosticMessageText(diag.messageText, '\n');
  return { file, line, col, code, cat, msg };
};

const changedSet = new Set(inProgram);
const report = [];
for (const sf of program.getSourceFiles()) {
  const abs = path.resolve(sf.fileName);
  if (!changedSet.has(abs)) continue;
  const semantic = program.getSemanticDiagnostics(sf);
  const syntactic = program.getSyntacticDiagnostics(sf);
  const suggestion = program.getSuggestionDiagnostics(sf);
  for (const d of [...syntactic, ...semantic]) report.push({ kind: 'diag', ...format(d) });
  for (const d of suggestion) report.push({ kind: 'suggestion', ...format(d) });
}

// App.tsx is outside include; compile it with same options plus its path
if (notInProgram.length) {
  const extraProgram = ts.createProgram({
    rootNames: [...parsed.fileNames, ...notInProgram],
    options: { ...parsed.options, noEmit: true },
  });
  for (const abs of notInProgram) {
    const sf = extraProgram.getSourceFile(abs);
    if (!sf) {
      console.log('NO_SOURCE_FILE', path.relative(root, abs));
      continue;
    }
    const semantic = extraProgram.getSemanticDiagnostics(sf);
    const syntactic = extraProgram.getSyntacticDiagnostics(sf);
    const suggestion = extraProgram.getSuggestionDiagnostics(sf);
    for (const d of [...syntactic, ...semantic]) report.push({ kind: 'diag-extra', ...format(d) });
    for (const d of suggestion) report.push({ kind: 'suggestion-extra', ...format(d) });
  }
}

const byFile = {};
for (const r of report) {
  (byFile[r.file] ||= []).push(r);
}
console.log('=== DIAGNOSTICS FOR CHANGED FILES ===');
if (!report.length) console.log('NONE');
for (const [file, items] of Object.entries(byFile).sort()) {
  console.log('\nFILE', file, 'count', items.length);
  for (const i of items) {
    console.log(`  [${i.kind}] ${i.code} ${i.cat} ${i.file}:${i.line}:${i.col} ${i.msg}`);
  }
}
